		return BK_FAIL;

	s_pm_cb_module_cfg.cfg[cfg->cb_module].cb_func = cfg->cb_func;

	return BK_OK;
}

bk_err_t pm_extern32k_unregister_cb(pm_cb_extern32k_cfg_t *cfg)
{
	if (cfg == NULL)
		return BK_FAIL;

	s_pm_cb_module_cfg.cfg[cfg->cb_module].cb_func = NULL;

	return BK_OK;
}

